export const economicsQuestionsExtended: QuizQuestion[] = [
  { id: 53, question: "Sefer çarterinde (voyage charter) yakıt masrafını kim üstlenir?", options: ["Acente", "Liman idaresi", "Kiracı (charterer)", "Donatan (owner)"], correctAnswer: 3, explanation: "Sefer çarterinde donatan gemiyi işletir; yakıt, liman masrafı ve mürettebat giderleri navlunun içindedir.", category: "Çarter Türleri" },
  { id: 54, question: "Zaman çarterinde (time charter) yakıt masrafı kime aittir?", options: ["Acenteye", "Sigortacıya", "Kiracıya", "Donatana"], correctAnswer: 2, explanation: "Zaman çarterinde kiracı gemiyi ticari olarak yönetir; yakıt ve liman masrafları ona, teknik işletme ve mürettebat donatana aittir.", category: "Çarter Türleri" },
  { id: 55, question: "Bareboat (çıplak gemi) çarterinin temel özelliği nedir?", options: ["Kiracı gemiyi mürettebatsız devralır ve işletmeyi üstlenir", "Donatan mürettebat, bakım ve sigortayı sağlamayı sürdürür", "Kiralama tek bir seferle ve tek yükle sınırlı tutulur", "Donatan yakıt ve liman masraflarını üstlenmeye devam etmektedir"], correctAnswer: 0, explanation: "Bareboat'ta kiracı hem ticari hem teknik işletmeden sorumludur; donatan yalnızca gemiyi finanse eden taraf konumundadır.", category: "Çarter Türleri" },
  { id: 56, question: "Contract of Affreightment (COA) neyi düzenler?", options: ["Belirli dönemde belirli miktar yükün çok seferde taşınması", "Geminin mülkiyetinin bedel karşılığı devredilmesi işlemi", "Geminin belirli bir süre için kiracıya tahsis edilmesi işlemi", "Tek bir seferde tek yükün taşınmasına ilişkin anlaşma"], correctAnswer: 0, explanation: "COA'da belirli bir gemi değil, taşınacak yük miktarı ve dönem taahhüt edilir; taşıyan gemi seçiminde esnektir.", category: "Çarter Türleri" },
  { id: 57, question: "Trip time charter nedir?", options: ["Gemi mülkiyetinin devri karşılığında bedel ödenmesi", "Belirli bir sefer için zaman çarteri esasıyla kiralama", "Yükün taşıma boyunca hasara karşı sigortalanması işlemi", "Süre sınırı olmaksızın süresiz olarak yapılan kiralama"], correctAnswer: 1, explanation: "Ücret günlük hire olarak ödenir fakat kiralama tek bir sefer ile sınırlıdır; masraf dağılımı zaman çarteri gibidir.", category: "Çarter Türleri" },
  { id: 58, question: "Çarter partide 'safe port' garantisi neyi ifade eder?", options: ["Limanda 24 saat kılavuz ve römorkör hizmeti bulunması", "Liman hizmetlerinin ücretsiz olarak verilmesi", "Gemi gidip kalıp dönebilmesinin emniyetli olması", "Limanın rota üzerinde ve yakın mesafede olması"], correctAnswer: 2, explanation: "Kiracı emniyetli liman göstermekle yükümlüdür; liman iyi denizcilikle güvenle kullanılamıyorsa kiracı sorumlu olur.", category: "Çarter Parti Maddeleri" },
  { id: 59, question: "'Off-hire' maddesi neyi düzenler?", options: ["Yakıt fiyatındaki değişimin kiraya nasıl yansıyacağını", "Sigorta priminin taraflar arasında paylaşımını", "Navlun ödemesinin hangi hesaba yapılacağını", "Gemi hizmet veremediğinde hire ödemesinin durmasını"], correctAnswer: 3, explanation: "Arıza, personel eksikliği veya tutulma gibi nedenlerle gemi kullanılamadığında kira işlemez; kapsam çarter partide ayrıntılı yazılır.", category: "Çarter Parti Maddeleri" },
  { id: 60, question: "Zaman çarterinde 'employment and indemnity' maddesi ne sağlar?", options: ["Mürettebat ücretlerinin hangi tarafa ait olduğunu", "Kaptanın ticari talimatlara uyması ve donatanın tazmini", "Yakıt tedarikinin hangi limanda yapılacağını ve kalitesini", "Sigorta kapsamının savaş riskini içerip içermediğini"], correctAnswer: 1, explanation: "Kaptan ticari talimatlara uyar; bu talimatlardan doğan zararlar kiracı tarafından tazmin edilir. Emniyet kararları kaptanda kalır.", category: "Çarter Parti Maddeleri" },
  { id: 61, question: "'Ice clause' hangi durumda devreye girer?", options: ["Buz nedeniyle limana erişimin tehlikeli hâle gelmesi", "Sis nedeniyle görüş mesafesinin belirgin azalması hâli", "Fırtına nedeniyle rıhtımda kalmanın riskli olması hâli", "Yükün soğuk nedeniyle donarak akışkanlığını yitirmesi"], correctAnswer: 0, explanation: "Madde, geminin buzlu limana girmeye zorlanamayacağını ve alternatif liman/tahliye düzenini belirler.", category: "Çarter Parti Maddeleri" },
  { id: 62, question: "'War risk' maddesi taşıyana ne imkânı verir?", options: ["Yükü en yakın emniyetli limanda boşaltma zorunluluğu", "Sözleşmeyi tek taraflı feshetme zorunluluğu getirmesi", "Navlunu piyasa endeksine göre yükseltme hakkı vermesi", "Riskli bölgeye girmeyi reddetme veya ek prim isteme"], correctAnswer: 3, explanation: "Madde, riskli bölgede ek savaş riski primi ve mürettebat ikramiyesinin kimin karşılayacağını da düzenler.", category: "Çarter Parti Maddeleri" },
  { id: 63, question: "Çarter partide 'cancelling date' (canceling) ne anlama gelir?", options: ["Sigorta poliçesinin geçerlilik bitiş tarihi", "Navlunun ödenmesi gereken son ödeme tarihi", "Geminin yükleme limanında hazır olacağı son tarih", "Boşaltmanın tamamlanması gereken son tarih"], correctAnswer: 2, explanation: "Gemi bu tarihe kadar hazır olmazsa kiracı sözleşmeyi feshetme hakkını kullanabilir; laycan aralığının bitiş tarihidir.", category: "Çarter Parti Maddeleri" },
  { id: 64, question: "'Laycan' terimi neyi ifade eder?", options: ["Boşaltma için kiracıya tanınan toplam süre", "Demuraj tahakkuk etmeye başladığı andan itibaren süre", "Yükleme için kiracıya tanınan sözleşmesel süre", "Geminin yüklemeye hazır olabileceği tarih aralığı"], correctAnswer: 3, explanation: "Laydays başlangıcı ile cancelling tarihi arasındaki aralıktır; gemi bu pencerede NOR verebilmelidir.", category: "Laytime/NOR" },
  { id: 65, question: "NOR (Notice of Readiness) geçerli olması için hangi koşul gerekir?", options: ["Geminin fiilen ve hukuken hazır olması gerekir", "Geminin demir yerinde demirlemiş olması gerekir", "Acenteye telefonla bildirim yapılması gerekir", "Geminin liman sınırına girmiş olması yeterlidir"], correctAnswer: 0, explanation: "Ambarlar hazır, serbest pratika ve gümrük işlemleri tamam olmalıdır; aksi hâlde NOR geçersiz sayılıp laytime başlamaz.", category: "Laytime/NOR" },
  { id: 66, question: "'Arrived ship' kavramı neden önemlidir?", options: ["Yük sigortasının riski üstlenmeye başlaması için", "Gümrük beyanının verilebilmesi için gerekli olduğu", "Yakıt tüketim hesabının kapatılabilmesi için", "Laytime'ın başlaması için varış noktasına ulaşması"], correctAnswer: 3, explanation: "Berth charter'da rıhtıma, port charter'da liman sınırlarına varış esastır; bu ayrım demuraj uyuşmazlıklarının temel konusudur.", category: "Laytime/NOR" },
  { id: 67, question: "NOR verildikten sonra laytime genellikle ne zaman başlar?", options: ["Gemi rıhtıma yanaştığı anda hemen başlar", "NOR verilir verilmez kesintisiz biçimde başlar", "Çarter partideki turn time süresi sonunda başlar", "İlk yük ambara alındığı anda başlamış olur"], correctAnswer: 2, explanation: "Tipik olarak NOR'dan 6 veya 12 saat sonra başlar; bu süre kiracıya hazırlık için tanınır.", category: "Laytime/NOR" },
  { id: 68, question: "'WWDSHEX' kısaltması ne anlama gelir?", options: ["Hava koşullarından bağımsız kesintisiz çalışma", "Weather Working Days, Sundays and Holidays Excepted", "Haftalık çalışma saatiyle sınırlı yükleme düzeni esası", "Tatil ayrımı olmaksızın sürekli çalışma esası"], correctAnswer: 1, explanation: "Yalnızca havanın çalışmaya elverdiği iş günleri sayılır; pazar ve tatiller laytime'a dahil edilmez.", category: "Laytime/NOR" },
  { id: 69, question: "Laytime aşıldığında ödenen tazminata ne ad verilir?", options: ["Navlun", "Hire", "Despatch", "Demuraj"], correctAnswer: 3, explanation: "Demuraj, kiracının kararlaştırılan süreyi aşması nedeniyle donatana ödediği götürü tazminattır.", category: "Laytime/NOR" },
  { id: 70, question: "Laytime'dan erken bitirilen süre için ödenen prime ne ad verilir?", options: ["Despatch", "Navlun", "Komisyon", "Demuraj"], correctAnswer: 0, explanation: "Despatch genellikle demuraj oranının yarısıdır ve donatan tarafından kiracıya ödenir.", category: "Laytime/NOR" },
  { id: 71, question: "Laytime 72 saat, kullanılan süre 96 saat ve demuraj 12,000 USD/gün ise demuraj bedeli kaç USD'dir?", options: ["6,000 USD", "9,000 USD", "12,000 USD", "24,000 USD"], correctAnswer: 2, explanation: "Aşım = 96 − 72 = 24 saat = 1 gün; demuraj = 1 × 12,000 = 12,000 USD.", category: "Laytime/NOR" },
  { id: 72, question: "Laytime 5 gün, kullanılan süre 3.5 gün ve despatch 6,000 USD/gün ise despatch tutarı kaç USD'dir?", options: ["12,000 USD", "3,000 USD", "6,000 USD", "9,000 USD"], correctAnswer: 3, explanation: "Tasarruf = 5 − 3.5 = 1.5 gün; despatch = 1.5 × 6,000 = 9,000 USD.", category: "Laytime/NOR" },
  { id: 73, question: "'Once on demurrage, always on demurrage' ilkesi neyi ifade eder?", options: ["Demuraj oranının sefer boyunca sabit kalmasını", "Demuraj başladıktan sonra istisnaların işlememesini", "Demuraj oranının aşımdan sonra iki katına çıkmasını", "Demurajın rıhtıma yanaşmayla birlikte sona ermesini"], correctAnswer: 1, explanation: "Demurajda geçen süre kesintisiz sayılır; hafta sonu veya kötü hava artık süreyi durdurmaz.", category: "Laytime/NOR" },
  { id: 74, question: "'Reversible laytime' ne sağlar?", options: ["Tanınan laytime süresinin iki katına çıkarılmasını", "Demuraj yükümlülüğünün tümüyle kaldırılmasını", "Laytime hesabının tek taraflı olarak iptalini", "Yükleme ve boşaltma sürelerinin toplu sayılmasını"], correctAnswer: 3, explanation: "Yükleme limanında kaybedilen süre, boşaltmada kazanılan süreyle mahsuplaşabilir; kiracıya esneklik sağlar.", category: "Laytime/NOR" },
  { id: 75, question: "Statement of Facts belgesinin laytime hesabındaki rolü nedir?", options: ["Yük sigortasının yürürlükte olduğunu kanıtlar", "Yükün cinsini ve miktarını resmen tanımlar", "Zaman damgalı olay kaydıyla süre hesabına esas olur", "Navlun oranını ve ödeme biçimini belirler"], correctAnswer: 2, explanation: "SOF'a dayanan Time Sheet, laytime'ın kullanımı ile demuraj/despatch tutarını gösterir ve taraflarca imzalanır.", category: "Laytime/NOR" },
  { id: 76, question: "'Freight' (navlun) neyi ifade eder?", options: ["Limanda verilen hizmetler için ödenen bedeli", "Yükün taşınması karşılığında ödenen bedeli", "Geminin günlük kirası olarak ödenen bedeli", "Yakıt ikmali için ödenen toplam bedeli"], correctAnswer: 1, explanation: "Navlun genellikle ton başına veya götürü (lumpsum) olarak belirlenir ve sefer çarterinin temel gelir kalemidir.", category: "Navlun/TCE" },
  { id: 77, question: "'Lumpsum freight' nasıl hesaplanır?", options: ["Yük miktarından bağımsız sefer için sabit tutar", "Sefer süresine bağlı günlük oran üzerinden", "Katedilen mesafeye bağlı birim oran üzerinden", "Fiilen taşınan yük miktarı üzerinden hesaplanır"], correctAnswer: 0, explanation: "Götürü navlunda gemi kapasitesi tahsis edilir; kiracı daha az yüklese bile tam tutarı öder.", category: "Navlun/TCE" },
  { id: 78, question: "'Deadfreight' ne anlama gelir?", options: ["Boş konteynerin geri gönderim ücretini ifade eder", "Yakıt fiyat farkının navluna yansıtılmasını ifade eder", "Hasar gören yükün sigorta bedelini ifade eder", "Eksik yüklenen kısım için ödenen navlunu ifade eder"], correctAnswer: 3, explanation: "Kiracı sözleşmedeki miktarı yükleyemezse, taşınmayan kısım için de navlun ödemekle yükümlüdür.", category: "Navlun/TCE" },
  { id: 79, question: "TCE hesabında sefer gelirinden hangi kalemler düşülür?", options: ["Yalnızca broker komisyonu ve adres komisyonu", "Mürettebat, bakım ve sigorta gibi işletme giderleri", "Yakıt, liman, kanal ve acente gibi sefer masrafları", "Amortisman ve kredi faizi gibi finansman giderleri"], correctAnswer: 2, explanation: "TCE yalnızca sefer masraflarını düşer; OPEX ve finansman giderleri düşülmez, çünkü amaç sonucun zaman çarteri hire oranıyla karşılaştırılabilmesidir.", category: "Navlun/TCE" },
  { id: 80, question: "Sefer geliri 640,000 USD, sefer masrafları 280,000 USD ve sefer süresi 24 gün ise TCE kaç USD/gün'dür?", options: ["15,000 USD/gün", "18,333 USD/gün", "26,667 USD/gün", "11,667 USD/gün"], correctAnswer: 0, explanation: "TCE = (640,000 − 280,000)/24 = 360,000/24 = 15,000 USD/gün.", category: "Navlun/TCE" },
  { id: 81, question: "35,000 ton yük 24 USD/ton navlunla taşınırsa brüt navlun kaç USD'dir?", options: ["900,000 USD", "700,000 USD", "780,000 USD", "840,000 USD"], correctAnswer: 3, explanation: "Navlun = 35,000 × 24 = 840,000 USD.", category: "Navlun/TCE" },
  { id: 82, question: "Brüt navlun 840,000 USD ve broker komisyonu %2.5 ise komisyon tutarı kaç USD'dir?", options: ["25,200 USD", "33,600 USD", "16,800 USD", "21,000 USD"], correctAnswer: 3, explanation: "Komisyon = 840,000 × 0.025 = 21,000 USD; net navlun 819,000 USD olur.", category: "Navlun/TCE" },
  { id: 83, question: "'Freight prepaid' konişmento kaydı ne anlama gelir?", options: ["Navlunun ödenmeyeceğini", "Navlunun varışta ödeneceğini", "Navlunun yüklemede peşin ödendiğini", "Navlunun taksitli olduğunu"], correctAnswer: 2, explanation: "Freight collect ise navlunun varışta alıcı tarafından ödeneceğini gösterir; akreditif işlemlerinde bu kayıt kritiktir.", category: "Navlun/TCE" },
  { id: 84, question: "Zaman çarterinde günlük hire 18,500 USD ve kiralama 45 gün ise brüt hire kaç USD'dir?", options: ["925,000 USD", "1,110,000 USD", "740,000 USD", "832,500 USD"], correctAnswer: 3, explanation: "Hire = 18,500 × 45 = 832,500 USD; komisyon ve off-hire süreleri ayrıca düşülür.", category: "Navlun/TCE" },
  { id: 85, question: "Hire ödemesi genellikle hangi periyotta yapılır?", options: ["Sefer bitiminde tek kalemde ve toplu olarak", "15 veya 30 günlük peşin dilimler hâlinde", "Her gün sonunda günlük olarak ödenir", "Yılda bir kez toplu olarak ödenir"], correctAnswer: 1, explanation: "Hire peşin ödenir; ödemedeki gecikme donatana gemiyi geri çekme (withdrawal) hakkı verebilir.", category: "Navlun/TCE" },
  { id: 86, question: "Konişmentonun 'kıymetli evrak' işlevi ne anlama gelir?", options: ["Ciro edilerek yük üzerindeki hakkın devredilebilmesi", "Gümrük beyanına esas alınan resmi belge olması", "Yükün teslim alındığını gösteren makbuz olması", "Yük sigortasının varlığını kanıtlayan resmi belge olması"], correctAnswer: 0, explanation: "Emre yazılı konişmento devredilebilir; yükü teslim alma hakkı belgeyi elinde bulundurana geçer.", category: "Konişmento/Hague-Visby" },
  { id: 87, question: "Hague-Visby Kuralları'nda taşıyanın temel yükümlülüğü nedir?", options: ["En kısa rotayı seçerek sefer süresini kısaltmak", "Liman masrafı en düşük limanı tercih etmek", "Yükü tam değeri üzerinden sigortalatmak", "Sefer başında gemiyi denize elverişli kılmak"], correctAnswer: 3, explanation: "'Due diligence' yükümlülüğü sefer başlangıcında geçerlidir; gemi, mürettebat ve yük mahallerinin uygunluğunu kapsar.", category: "Konişmento/Hague-Visby" },
  { id: 88, question: "Hague-Visby'de sorumluluk sınırı nasıl belirlenir?", options: ["Yalnızca beyan edilen yük değerine göre", "Sözleşmede yazılı sabit bir tutar üzerinden", "Koli başına 666.67 SDR veya kg başına 2 SDR", "Yalnızca yükün brüt ağırlığına göre"], correctAnswer: 2, explanation: "İki ölçütten yüksek olanı uygulanır; yükün değeri konişmentoda beyan edilmişse sınır uygulanmayabilir.", category: "Konişmento/Hague-Visby" },
  { id: 89, question: "Hague-Visby'de 'nautical fault' istisnası neyi kapsar?", options: ["Yükün ambalajındaki kusur ve eksikliklerin tümünü", "Varışta ortaya çıkan gecikme zararlarını", "Yükleme sırasındaki istif hatalarını", "Geminin sevk ve idaresindeki hata veya ihmali"], correctAnswer: 3, explanation: "Seyir ve gemi yönetimindeki hatalar taşıyanı sorumluluktan kurtarır; ancak yükün bakımındaki ihmal bu istisnaya girmez.", category: "Konişmento/Hague-Visby" },
  { id: 90, question: "Hamburg Kuralları'nın Hague-Visby'den temel farkı nedir?", options: ["Sorumluluğu genişletip nautical fault istisnasını kaldırma", "Yalnızca konteyner taşımalarına uygulanabilir olması", "Yalnızca tanker ve gaz taşıyıcılarına uygulanması", "Sorumluluk sınırını Hague-Visby'nin altına indirmesi"], correctAnswer: 0, explanation: "Hamburg Kuralları yük sahibi lehine daha geniş sorumluluk getirir; ancak büyük denizci devletlerce yaygın biçimde benimsenmemiştir.", category: "Konişmento/Hague-Visby" },
  { id: 91, question: "Rotterdam Kuralları neyi hedefler?", options: ["Yalnızca çarter parti sözleşmelerini düzenlemeyi", "Yalnızca yük sigortası kapsamını belirlemeyi", "Yalnızca deniz ayağındaki taşımayı düzenlemeyi", "Kapıdan kapıya taşıma ve e-belgeleri kapsamayı"], correctAnswer: 3, explanation: "Rotterdam Kuralları çok modlu taşımayı ve e-konişmentoyu düzenler; henüz geniş yürürlük kazanmamıştır.", category: "Konişmento/Hague-Visby" },
  { id: 92, question: "Sea waybill ile konişmento arasındaki temel fark nedir?", options: ["Sea waybill sigortalıdır", "Fark yoktur", "Sea waybill devredilemez", "Sea waybill daha ucuzdur"], correctAnswer: 2, explanation: "Sea waybill kıymetli evrak değildir; yük, belge ibrazı olmadan adı yazılı alıcıya teslim edilir. Kısa seferlerde tercih edilir.", category: "Konişmento/Hague-Visby" },
  { id: 93, question: "Incoterms 2020'de FOB terimi neyi ifade eder?", options: ["Satıcı yükü varış limanına kadar taşıyıp teslim eder", "Satıcının yükümlülüğü gemiye yüklemeyle sona erer", "Alıcı yalnızca ithalat gümrüğünü öder", "Satıcı navlun ve sigortayı birlikte üstlenir"], correctAnswer: 1, explanation: "FOB'da risk yük gemiye yüklendiğinde alıcıya geçer; navlun ve sigorta alıcıya aittir.", category: "Incoterms 2020" },
  { id: 94, question: "Incoterms 2020'de CIF hangi yükümlülükleri satıcıya verir?", options: ["Yalnızca yük sigortasını yaptırma yükümlülüğü", "Taşımaya ilişkin hiçbir yükümlülük vermez", "Yalnızca gemiye yükleme yükümlülüğü verir", "Navlun ve asgari düzeyde yük sigortasını"], correctAnswer: 3, explanation: "CIF'te satıcı navlunu ve sigortayı öder; ancak risk yine yükleme limanında gemiye yüklemeyle alıcıya geçer.", category: "Incoterms 2020" },
  { id: 95, question: "Incoterms 2020'de CFR ile CIF arasındaki fark nedir?", options: ["CIF'te satıcının ayrıca sigorta yaptırması", "Malın teslim edildiği yerin farklı olması", "Riskin alıcıya geçtiği anın farklı olması", "Navlunu hangi tarafın ödediğinin farklı olması"], correctAnswer: 0, explanation: "İkisinde de navlunu satıcı öder ve risk yüklemede geçer; tek fark CIF'te sigorta yükümlülüğünün satıcıda olmasıdır.", category: "Incoterms 2020" },
  { id: 96, question: "Incoterms 2020'de DAP terimi neyi belirtir?", options: ["İthalat gümrüğü ödenmiş olarak teslim", "Satıcının kendi işyerinde teslim", "Varış yerinde, boşaltılmadan teslim", "Yükleme limanında gemide teslim"], correctAnswer: 2, explanation: "DAP'ta satıcı yükü varış yerine getirir ancak boşaltma ve ithalat gümrüğü alıcıya aittir; DDP'de gümrük de satıcıdadır.", category: "Incoterms 2020" },
  { id: 97, question: "Incoterms 2020'de EXW teriminde risk nerede alıcıya geçer?", options: ["Yük gemiye yüklendiği anda alıcı tarafa geçer", "İhracat gümrüğü tamamlandığında geçer", "Yük varış limanına ulaştığında geçer", "Satıcının işyerinde emre hazır edildiğinde"], correctAnswer: 3, explanation: "EXW satıcı için en az yükümlülük içeren terimdir; tüm taşıma, gümrük ve risk alıcıya aittir.", category: "Incoterms 2020" },
  { id: 98, question: "Incoterms 2020'de hangi terimler yalnızca deniz ve iç su yolu taşımasında kullanılır?", options: ["EXW, FCA, CPT, CIP", "FAS, FOB, CFR, CIF", "DAP, DPU, DDP", "Hepsi"], correctAnswer: 1, explanation: "Bu dört terim gemiye/gemiden teslim kavramına dayandığı için yalnızca su yolu taşımasında kullanılır.", category: "Incoterms 2020" },
  { id: 99, question: "P&I sigortası temel olarak neyi karşılar?", options: ["Taşınan yükün konişmentoda beyan edilen değerini", "Sefer gelirindeki navlun kaybını", "Gemi gövdesindeki fiziksel hasarı", "Üçüncü kişilere karşı sorumlulukları"], correctAnswer: 3, explanation: "Yük hasarı, mürettebat yaralanması, kirlilik ve çatışmadan doğan sorumluluklar P&I kapsamındadır.", category: "Sigorta (P&I/H&M)" },
  { id: 100, question: "H&M (Hull & Machinery) sigortası neyi kapsar?", options: ["Mürettebatın sağlık ve tedavi masraflarını", "Üçüncü kişilere karşı doğan sorumluluğu", "Geminin kendi gövde ve makine hasarını", "Taşınan yükün hasar ve eksikliğini"], correctAnswer: 2, explanation: "H&M donatanın kendi malvarlığındaki hasarı; P&I ise üçüncü kişilere karşı sorumluluğu karşılar.", category: "Sigorta (P&I/H&M)" },
  { id: 101, question: "P&I kulüplerinin karşılıklılık (mutuality) esası ne anlama gelir?", options: ["Devlet güvencesiyle desteklenmiş olmaları", "Tek bir donatana hizmet vermeleri", "Kâr amacıyla kurulmuş olmaları", "Üyelerin birbirini aidatla sigortalaması"], correctAnswer: 3, explanation: "Kulüpler kâr amacı gütmez; öngörülenden yüksek hasarlarda üyelerden ek çağrı (supplementary call) istenebilir.", category: "Sigorta (P&I/H&M)" },
  { id: 102, question: "'Deductible' (muafiyet) nedir?", options: ["Her hasarda sigortalının kendi üstlendiği tutar", "Sigortacının ödeyeceği azami tazminat limiti tutarı", "Brokere ödenen aracılık komisyonu tutarı", "Poliçe için ödenen yıllık sigorta primi"], correctAnswer: 0, explanation: "Muafiyetin yükseltilmesi primi düşürür; küçük hasarların sigortaya taşınmasını da engeller.", category: "Sigorta (P&I/H&M)" },
  { id: 103, question: "Sigorta bedeli 24,000,000 USD ve prim oranı %0.35 ise yıllık prim kaç USD'dir?", options: ["96,000 USD", "48,000 USD", "72,000 USD", "84,000 USD"], correctAnswer: 3, explanation: "Prim = 24,000,000 × 0.0035 = 84,000 USD.", category: "Sigorta (P&I/H&M)" },
  { id: 104, question: "Müşterek avarya (general average) ne zaman söz konusu olur?", options: ["Yalnızca çatışma sonucu oluşan hasarlarda", "Gemide meydana gelen her türlü hasar hâlinde", "Ortak tehlikede kasıtlı fedakârlık yapıldığında", "Yalnızca yangın söndürme çalışmalarında"], correctAnswer: 2, explanation: "Fedakârlık ve olağanüstü masraflar gemi, yük ve navlun arasında değerleri oranında paylaştırılır.", category: "Sigorta (P&I/H&M)" },
  { id: 105, question: "Müşterek avaryada payların hesaplanması hangi kurallara göre yapılır?", options: ["York-Antwerp Kuralları", "Hague-Visby Kuralları", "Incoterms 2020 kuralları", "SOLAS Bölüm II-1 kuralları"], correctAnswer: 0, explanation: "York-Antwerp Kuralları avarya dispeçinin uluslararası standardını oluşturur ve çarter parti/konişmentolarda atıf yapılır.", category: "Sigorta (P&I/H&M)" },
  { id: 106, question: "'Particular average' neyi ifade eder?", options: ["Geminin tam ziyaını (total loss) ifade eder", "Kurtarma ücretinin paylaşımını ifade eder", "Ortak fedakârlığın paylaşımını ifade eder", "Zarara uğrayanın üstlendiği kısmi hasarı"], correctAnswer: 3, explanation: "Müşterek avaryadan farklı olarak paylaştırılmaz; zarar kime aitse onun sigortasınca karşılanır.", category: "Sigorta (P&I/H&M)" },
  { id: 107, question: "Kurtarma (salvage) ödülünün temel ilkesi nedir?", options: ["Kurtarma ekibine saatlik ücret ödenmesi", "Ödülün sigorta bedeliyle sınırlı olması", "Ödülün önceden sabit tarifeyle belirlenmesi", "No cure, no pay: başarı yoksa ödül yok"], correctAnswer: 3, explanation: "LOF sözleşmesinde ödül kurtarılan değerle ilişkilidir; çevresel zarar önlenmesi için SCOPIC gibi özel tazminat düzenlemeleri vardır.", category: "Sigorta (P&I/H&M)" },
  { id: 108, question: "Gemi işletme maliyetlerinde OPEX neyi kapsar?", options: ["Yalnızca sefer başına elde edilen navlunu", "Yakıt, liman ve kanal geçiş masraflarını", "Mürettebat, bakım, kumanya, sigorta ve yönetimi", "Kredi anapara ve faiz geri ödemelerini"], correctAnswer: 2, explanation: "OPEX gemi denizde olsun olmasın süren günlük işletme giderleridir; yakıt ve liman masrafı ise sefer masrafıdır (voyage cost).", category: "Gemi Maliyetleri" },
  { id: 109, question: "Sefer masrafları (voyage costs) hangi kalemleri içerir?", options: ["Tekne ve sorumluluk sigortası primleri", "Amortisman ve sermaye maliyeti kalemleri", "Mürettebat maaşı ve kumanya giderleri", "Yakıt, liman, kanal ve acente masrafları"], correctAnswer: 3, explanation: "Sefer masrafları sefere özgüdür ve zaman çarterinde kiracıya, sefer çarterinde donatana aittir.", category: "Gemi Maliyetleri" },
  { id: 110, question: "Günlük OPEX 6,800 USD olan bir gemi için yıllık işletme gideri yaklaşık kaç USD'dir?", options: ["1.75 milyon USD", "2.48 milyon USD", "3.10 milyon USD", "4.20 milyon USD"], correctAnswer: 1, explanation: "Yıllık = 6,800 × 365 ≈ 2,482,000 USD.", category: "Gemi Maliyetleri" },
  { id: 111, question: "Havuzlama (drydocking) maliyeti hangi gider grubuna girer?", options: ["Periyodik bakım gideri; ayrı bütçelenir", "Finansman gideri; faizle birlikte izlenir", "Navlun gideri; sefer gelirinden düşülür", "Sefer masrafı; kiracıya fatura edilir"], correctAnswer: 0, explanation: "Havuzlama düzenli aralıklarla tekrarlanır ve tutarı yüksek olduğundan genellikle yıllara yayılarak ayrı bütçelenir.", category: "Gemi Maliyetleri" },
  { id: 112, question: "'Lay-up' kararı hangi durumda alınır?", options: ["Yakıt fiyatları belirgin biçimde düştüğünde", "Gemi yeni teslim alınmış ve garantideyken", "Navlun piyasası zirveye yakın seyrederken", "Navlun geliri işletme maliyetini karşılamazken"], correctAnswer: 3, explanation: "Sıcak lay-up hızlı dönüşe imkân verirken maliyeti yüksektir; soğuk lay-up maliyeti düşürür fakat yeniden devreye alma süresi uzar.", category: "Gemi Maliyetleri" },
  { id: 113, question: "'Break-even' navlun oranı neyi ifade eder?", options: ["Piyasadaki ortalama navlun seviyesini", "Ulaşılabilir azami kâr seviyesini", "Kâr ve zararın sıfırlandığı oranı", "Sözleşmedeki asgari navlun oranını"], correctAnswer: 2, explanation: "İşletme, sefer ve finansman maliyetleri toplamının günlük eşdeğeridir; bu oranın altındaki seferler zarar üretir.", category: "Gemi Maliyetleri" },
  { id: 114, question: "Günlük OPEX 6,800 USD ve günlük finansman gideri 4,200 USD ise günlük break-even kaç USD'dir?", options: ["13,000 USD", "15,000 USD", "9,000 USD", "11,000 USD"], correctAnswer: 3, explanation: "Break-even = 6,800 + 4,200 = 11,000 USD/gün; sefer masrafları ayrıca navlundan karşılanmalıdır.", category: "Gemi Maliyetleri" },
  { id: 115, question: "Gemi finansmanında ipotek (mortgage) ne sağlar?", options: ["Kredi verene gemi üzerinde öncelikli teminat", "Kiracıya navlun ödemesi için garanti", "Donatana tonaj vergisinde indirim hakkı", "Sigortacıya rücu hakkından feragat"], correctAnswer: 0, explanation: "İpotek gemi siciline tescil edilir; borç ödenmezse kredi veren gemiyi sattırma hakkına sahiptir.", category: "Gemi Finansmanı" },
  { id: 116, question: "'Sale and leaseback' işlemi ne sağlar?", options: ["Yeni gemi siparişi için ön ödeme sağlar", "Sigorta priminde kalıcı indirim sağlar", "Gemiyi hurdaya ayırma imkânı sağlar", "Gemiyi satıp geri kiralayarak nakit sağlar"], correctAnswer: 3, explanation: "Donatan mülkiyeti devreder fakat gemiyi işletmeye devam eder; bilanço ve nakit akışı üzerinde önemli etkisi vardır.", category: "Gemi Finansmanı" },
  { id: 117, question: "Gemi kredilerinde 'loan to value' oranı neyi gösterir?", options: ["Broker komisyonunun kredi tutarına oranını", "Kredinin yıllık faiz oranı düzeyini", "Kredi tutarının gemi değerine oranını", "Kredinin kalan vade süresi uzunluğunu"], correctAnswer: 2, explanation: "Gemi değeri düştüğünde bu oran yükselir; sözleşmedeki minimum değer kaydı ihlal edilirse ek teminat istenir.", category: "Gemi Finansmanı" },
  { id: 118, question: "Gemi değeri 30 milyon USD ve kredi bakiyesi 21 milyon USD ise LTV oranı kaçtır?", options: ["%60", "%70", "%75", "%80"], correctAnswer: 1, explanation: "LTV = 21/30 = 0.70, yani %70.", category: "Gemi Finansmanı" },
  { id: 119, question: "Denizcilikte piyasa döngüsünün (shipping cycle) temel nedeni nedir?", options: ["Sigorta primlerindeki dönemsel dalgalanmalar", "Liman ücretlerinin yıllık olarak artması", "Yakıt fiyatlarındaki ani sıçramalar", "Gemi arzının inşa süresi nedeniyle gecikmesi"], correctAnswer: 3, explanation: "Yüksek navlun sipariş dalgası yaratır; gemiler 2–3 yıl sonra teslim edildiğinde talep düşmüş olabilir ve arz fazlası oluşur.", category: "Gemi Finansmanı" },
  { id: 120, question: "Baltic Dry Index neyi ölçer?", options: ["Kuru dökme yük navlun seviyesini", "Konteyner hattı navlunlarını", "Bunker yakıt fiyatlarını", "Ham petrol tankeri navlun seviyesini"], correctAnswer: 0, explanation: "BDI, Capesize–Panamax–Supramax gibi segmentlerin belirli rotalardaki navlun oranlarını birleştirir ve piyasa göstergesi kabul edilir.", category: "Gemi Finansmanı" },
  { id: 121, question: "Gemi alım satımında 'Memorandum of Agreement' (MOA) neyi düzenler?", options: ["Geminin süreli kiralanmasının şartlarını", "Yükün taşınmasının genel şartlarını", "İkinci el gemi satışının şartlarını", "Tekne ve makine sigortası şartlarını"], correctAnswer: 2, explanation: "Norwegian Saleform gibi standart formlar kullanılır; teslim yeri, muayene, depozito ve kusur hükümleri MOA'da yer alır.", category: "Gemi Finansmanı" },
  { id: 122, question: "Gemi hurda (demolition) değerini belirleyen temel etken nedir?", options: ["Geminin yük taşıma kapasitesi (DWT)", "Ana makinenin beyan edilen gücü", "Geminin inşa yılı ve klas geçmişi", "Hafif gemi ağırlığı ve hurda çelik fiyatı"], correctAnswer: 3, explanation: "Hurda bedeli genellikle USD/LDT olarak kote edilir; sökümün yapılacağı ülkenin çelik talebi fiyatı belirler.", category: "Gemi Finansmanı" },
  { id: 123, question: "LDT'si 9,500 ton olan bir gemi 480 USD/LDT'den satılırsa hurda bedeli kaç USD'dir?", options: ["4.1 milyon USD", "4.56 milyon USD", "5.2 milyon USD", "3.8 milyon USD"], correctAnswer: 1, explanation: "Bedel = 9,500 × 480 = 4,560,000 USD.", category: "Gemi Finansmanı" },
  { id: 124, question: "Bunker alımında 'MARPOL numunesi' neden alınır?", options: ["Teslim fiyatının doğrulanabilmesi için", "Yakıt yoğunluğunun ölçülebilmesi için", "Teslim edilen miktarın kanıtlanabilmesi için", "Kükürt içeriğinin denetimde kanıtlanması"], correctAnswer: 3, explanation: "Mühürlü numune gemide saklanır; uyuşmazlıkta ve PSC denetiminde referans alınır.", category: "Yakıt/Bunker" },
  { id: 125, question: "Bunker miktar uyuşmazlıklarının en yaygın nedeni nedir?", options: ["Barçtaki hava sıcaklığının yüksek olması", "Piyasa fiyatı ile fatura arasındaki fark", "Ölçüm farkları ve cappuccino bunker etkisi", "Yakıtın renginin beklenenden koyu olması"], correctAnswer: 2, explanation: "Yakıta hava karıştırılması hacmi şişirir; gemi kendi tank ölçümlerini yapmalı ve fark hâlinde protesto mektubu vermelidir.", category: "Yakıt/Bunker" },
  { id: 126, question: "Bunker hesabında hacimden kütleye geçerken hangi düzeltme gerekir?", options: ["Viskozite düzeltmesi ve akış hızı ölçümü", "Renk skalası düzeltmesi ve tortu payı", "Tank basıncı düzeltmesi ve hava payı", "Sıcaklık düzeltmesi ve 15 °C yoğunluğu"], correctAnswer: 3, explanation: "Yakıt sıcaklıkla genleşir; teslim sıcaklığındaki hacim VCF ile 15 °C'ye çevrilip yoğunlukla çarpılarak metrik ton bulunur.", category: "Yakıt/Bunker" },
  { id: 127, question: "15 °C'deki hacim 620 m³ ve yoğunluk 0.985 t/m³ ise yakıt kütlesi kaç tondur?", options: ["611 t", "629 t", "575 t", "590 t"], correctAnswer: 0, explanation: "Kütle = 620 × 0.985 = 610.7 ≈ 611 t.", category: "Yakıt/Bunker" },
  { id: 128, question: "Günde 28 ton yakıt tüketen bir gemi 12 günlük seferde kaç ton yakıt kullanır?", options: ["364 t", "280 t", "308 t", "336 t"], correctAnswer: 3, explanation: "Tüketim = 28 × 12 = 336 ton; ayrıca manevra, liman ve rezerv payı eklenir.", category: "Yakıt/Bunker" },
  { id: 129, question: "336 ton VLSFO 610 USD/ton fiyatla alınırsa maliyet kaç USD'dir?", options: ["164,640 USD", "184,240 USD", "204,960 USD", "224,560 USD"], correctAnswer: 2, explanation: "Maliyet = 336 × 610 = 204,960 USD.", category: "Yakıt/Bunker" },
  { id: 130, question: "'Bunker adjustment factor' (BAF) ne işe yarar?", options: ["Yakıt fiyatı değişiminin navluna yansıtılması", "Teslim edilen yakıt miktarının ölçülmesi", "Yakıt üzerindeki verginin hesaplanması", "Yakıtın ISO 8217 kalite sınıfının belirlenmesi"], correctAnswer: 0, explanation: "Özellikle konteyner hattı taşımacılığında kullanılır; yakıt fiyatı riski taşıyan ile yük sahibi arasında paylaşılır.", category: "Yakıt/Bunker" },
  { id: 131, question: "Zaman çarteri tesliminde bunker devri nasıl yapılır?", options: ["Bunker donatanda kalır, kiracı yeniden alır", "Kalan bunker limanda tesise teslim edilir", "Kalan bunker kiracıya ücretsiz devredilir", "Teslim miktarı kararlaştırılan fiyatla satılır"], correctAnswer: 3, explanation: "Teslim (delivery) ve iade (redelivery) anlarındaki bunker miktar ve fiyatları çarter partide açıkça belirlenir.", category: "Yakıt/Bunker" },
  { id: 132, question: "Yakıt kalitesi uyuşmazlığında geminin ilk yapması gereken nedir?", options: ["Şüpheli yakıtı kullanmadan denize basmak", "Şüpheli yakıtı temiz yakıtla karıştırmak", "Şüpheli yakıtı düşük yükte kullanmayı denemek", "Yakıtı izole edip numuneyi analize göndermek"], correctAnswer: 3, explanation: "Şüpheli yakıtın kullanılması ağır makine hasarına yol açabilir; izolasyon ve zamanında protesto hukuki hakları korur.", category: "Yakıt/Bunker" },
  { id: 133, question: "Zaman çarterinde 'speed and consumption' garantisi neyi taahhüt eder?", options: ["Sefer başına ödenecek toplam navlun tutarını", "Yükleme ve boşaltma hızını (ton/gün)", "Belirli havada hız ve yakıt tüketimini", "Limanda geçirilecek azami süreyi"], correctAnswer: 2, explanation: "Garanti sağlanamazsa kiracı performans talebinde bulunabilir; gövde kirlenmesi ve hava koşulu değerlendirmesi uyuşmazlık konusudur.", category: "Çarter Parti Maddeleri" },
  { id: 134, question: "'Good weather' tanımı performans hesabında neden kritiktir?", options: ["Savaş riski sigortası kapsamı için", "Büyük daire rotası seçimi için", "Yolcu ve mürettebat konforu için", "Garantinin yalnızca bu koşulda ölçülmesi"], correctAnswer: 3, explanation: "Genellikle Beaufort 4 ve Douglas 3'e kadar olan dönemler esas alınır; tanım farkları performans iddialarının çekirdeğidir.", category: "Çarter Parti Maddeleri" },
  { id: 135, question: "Çarter partide 'BIMCO' formlarının kullanılmasının yararı nedir?", options: ["Kullanımlarının tümüyle ücretsiz olması", "Yorumu yerleşik standart metinler sunması", "Diğer formlardan daha kısa olmaları", "Bayrak devletlerince zorunlu tutulması"], correctAnswer: 1, explanation: "GENCON, NYPE, BARECON gibi formlar taraflara öngörülebilirlik sağlar; uyuşmazlıklarda içtihat birikimi mevcuttur.", category: "Çarter Parti Maddeleri" },
  { id: 136, question: "Çarter partide uyuşmazlıkların çözümü genellikle nasıl öngörülür?", options: ["Tahkim (Londra veya New York tahkimi)", "Yükleme limanındaki liman idaresinin kararı", "Donatanın P&I kulübünün hakemliği", "Kiracının yerleşim yerindeki mahkeme"], correctAnswer: 0, explanation: "Denizcilik uyuşmazlıklarında tahkim yaygındır; uzmanlık, gizlilik ve kararların uluslararası tanınırlığı başlıca gerekçelerdir.", category: "Çarter Parti Maddeleri" },
  { id: 137, question: "'Lien on cargo' (yük üzerinde hapis hakkı) ne sağlar?", options: ["Yükü donatan adına sigortalatma hakkını", "Yükü başka bir yükle değiştirebilme hakkını", "Yükü açık artırmayla satma hakkını", "Ödenmeyen navlun için yükü teslim etmeme"], correctAnswer: 3, explanation: "Hapis hakkının kullanılabilmesi için çarter partide açıkça öngörülmesi ve konişmentoya yansıtılması gerekir.", category: "Çarter Parti Maddeleri" },
  { id: 138, question: "'Himalaya clause' kimi korur?", options: ["Yükü sigortalayan sigorta şirketini korur", "Gemi malikini ve donatanı korur", "Taşıyanın çalışanı ve alt yüklenicisini", "Yük sahibi ve göndericiyi korur"], correctAnswer: 2, explanation: "Madde, taşıyanın sahip olduğu sorumluluk sınırlarından acente, terminal işletmecisi ve mürettebatın da yararlanmasını sağlar.", category: "Konişmento/Hague-Visby" },
  { id: 139, question: "'Paramount clause' konişmentoda neyi belirler?", options: ["Yükleme ve boşaltma limanlarını belirler", "Taşınacak yükün cinsini ve miktarını", "Navlun oranını ve ödeme biçimini", "Uygulanacak taşıma rejimini belirler"], correctAnswer: 3, explanation: "Madde, taşıma sözleşmesine hangi kural setinin emredici biçimde uygulanacağını açıkça gösterir.", category: "Konişmento/Hague-Visby" },
  { id: 140, question: "Konişmentoda 'said to contain' (STC) kaydı ne anlama gelir?", options: ["İçeriğin yükleten beyanına dayandığını", "Yükün hasarlı teslim alındığını", "Yükün sigorta kapsamında olduğunu", "Yükün taşıyanca tek tek sayıldığını"], correctAnswer: 0, explanation: "Mühürlü konteynerlerde içerik kontrol edilemediğinden bu kayıt kullanılır; taşıyanın sorumluluğunu sınırlamaya yardımcı olur.", category: "Konişmento/Hague-Visby" },
  { id: 141, question: "Konteyner taşımacılığında 'demurrage' ve 'detention' farkı nedir?", options: ["Demurrage yalnızca gemi için tahakkuk eder", "Detention yalnızca ihracat yükünde doğar", "İkisi aynı ücretin farklı adlarıdır", "Demurrage terminal içi, detention terminal dışı"], correctAnswer: 3, explanation: "İki ücret farklı serbest sürelere tabidir; alıcı gecikmesi her ikisini de tetikleyebilir.", category: "Laytime/NOR" },
  { id: 142, question: "Liner taşımacılığı ile tramp taşımacılığı arasındaki temel fark nedir?", options: ["Gemilerin bayrak devletinin farklı olması", "Gemi büyüklüğü ve tonajının farklı olması", "Liner tarifeli hat, tramp serbest sefer yapar", "Taşınan yük türünün kesin olarak farklı olması"], correctAnswer: 2, explanation: "Liner ilan edilmiş tarife ve limanlarla çalışır; tramp gemisi ise piyasada en iyi navlunu bulduğu yere gider.", category: "Çarter Türleri" },
  { id: 143, question: "Denizcilikte 'freight forwarder' hangi işlevi görür?", options: ["Gemiyi teknik olarak işletmek ve donatmak", "Yük sahibi adına taşımayı organize etmek", "Liman terminalini işletmek ve tahsis etmek", "Yük ve tekne sigortası poliçesi satmak"], correctAnswer: 1, explanation: "Taşıma modlarını birleştirir, belge ve gümrük işlemlerini yürütür; kimi zaman NVOCC olarak kendi konişmentosunu düzenler.", category: "Çarter Türleri" },
  { id: 144, question: "Gemi acentesinin temel görevi nedir?", options: ["Donatan adına yeni gemi inşa siparişi vermek", "Donatan adına sigorta poliçesi yapmak", "Donatan adına yükü piyasada satmak", "Donatan adına liman işlemlerini yürütmek"], correctAnswer: 3, explanation: "Yanaşma, gümrük, kumanya, personel değişimi ve resmî bildirimler acente tarafından koordine edilir.", category: "Çarter Türleri" },
  { id: 145, question: "Brokerin (shipbroker) rolü nedir?", options: ["Çarter veya alım satıma aracılık etmek", "Yükü ve tekneyi sigorta ettirmek", "Liman ve terminal tesisini işletmek", "Gemiyi ticari olarak işletip yönetmektir"], correctAnswer: 0, explanation: "Broker piyasa bilgisi sağlar ve pazarlığı yürütür; geliri genellikle navlun veya satış bedeli üzerinden komisyondur.", category: "Çarter Türleri" },
  { id: 146, question: "'Fixture' terimi ne anlama gelir?", options: ["Yükün ambarlara istif planını", "Gemideki sabit donanım ve ekipmanı", "Anlaşmaya varılmış çarter işlemini", "Liman hizmetleri için kesilen ücreti"], correctAnswer: 2, explanation: "Fixture recap, anlaşmanın ana şartlarını özetler ve çarter parti hazırlanana kadar bağlayıcı kabul edilir.", category: "Çarter Türleri" },
  { id: 147, question: "'Subjects' (subs) kaydı müzakerede neyi ifade eder?", options: ["Navlunun peşin olarak ödendiğini", "Geminin yüklemeye hazır olduğunu", "Anlaşmanın kesinleşmiş olduğunu", "Anlaşmanın onaylara bağlı olduğunu"], correctAnswer: 3, explanation: "Örneğin 'sub stem' veya 'sub board approval'; bu şartlar kaldırılmadan (lifted) sözleşme bağlayıcı hâle gelmez.", category: "Çarter Türleri" },
  { id: 148, question: "Panama Kanalı geçiş ücreti temel olarak neye göre belirlenir?", options: ["Geminin inşa yılı ve klas durumuna", "Gemi tipi, boyutu ve yük kapasitesine", "Gemideki mürettebat mevcuduna göre", "Geminin sicile kayıtlı bayrağına"], correctAnswer: 1, explanation: "Konteyner gemilerinde TEU kapasitesi, diğerlerinde PC/UMS tonajı esas alınır; su rezervuar ücreti gibi ek kalemler de eklenebilir.", category: "Gemi Maliyetleri" },
  { id: 149, question: "Süveyş Kanalı'nın rota üzerindeki temel ekonomik etkisi nedir?", options: ["Yük ve tekne sigortasını ucuzlatması", "Uğranan limanların ücretini düşürmesi", "Bunker yakıt fiyatını düşürmesi", "Asya-Avrupa mesafesini kısaltması"], correctAnswer: 3, explanation: "Ümit Burnu alternatifine göre önemli mesafe tasarrufu sağlar; geçiş ücreti ile bu tasarruf karşılaştırılarak rota seçilir.", category: "Gemi Maliyetleri" },
  { id: 150, question: "Kanal geçişi 380,000 USD tutuyor; alternatif rota 9 gün ek süre getiriyor ve günlük toplam maliyet 22,000 USD ise hangisi daha ekonomiktir?", options: ["İkisi de aynı maliyettedir", "Yalnızca navlun bilinirse karşılaştırılabilir", "Alternatif rota; 182,000 USD tasarruf sağlar", "Kanal geçişi; 182,000 USD tasarruf sağlar"], correctAnswer: 2, explanation: "Alternatif rotanın ek maliyeti = 9 × 22,000 = 198,000 USD; kanal ücreti 380,000 USD olduğundan fark 380,000 − 198,000 = 182,000 USD alternatif rota lehinedir.", category: "Gemi Maliyetleri" },
  { id: 151, question: "Sefer kârlılığı değerlendirilirken hangi ölçüt kullanılır?", options: ["Taşınan yükün toplam tonaj miktarı", "Seferde katedilen toplam yol mesafesi", "Elde edilen brüt navlun geliri tutarı", "TCE'nin break-even oranıyla kıyaslanması"], correctAnswer: 3, explanation: "Yüksek brüt navlun, uzun sefer süresi veya yüksek yakıt maliyetiyle birlikte düşük TCE üretebilir; karar TCE üzerinden verilir.", category: "Navlun/TCE" },
  { id: 152, question: "Sefer geliri 900,000 USD, yakıt 260,000 USD, liman ve kanal masrafı 190,000 USD ve sefer 30 gün ise TCE kaç USD/gün'dür?", options: ["16,667 USD/gün", "21,000 USD/gün", "13,000 USD/gün", "15,000 USD/gün"], correctAnswer: 0, explanation: "TCE = (900,000 − 260,000 − 190,000)/30 = 450,000/30 = 15,000 USD/gün.", category: "Navlun/TCE" },
  { id: 153, question: "Yakıt fiyatı arttığında yavaş seyrin ekonomik cazibesi nasıl değişir?", options: ["Cazibesi yakıt fiyatından bağımsızdır", "Cazibesi yalnızca navlun düzeyine bağlıdır", "Cazibesi azalır, zaman kaybı ağır basar", "Cazibesi artar, yakıt tasarrufu öne geçer"], correctAnswer: 3, explanation: "Karar; yakıt fiyatı, navlun seviyesi ve alternatif sefer fırsat maliyetinin birlikte değerlendirilmesiyle verilir.", category: "Yakıt/Bunker" },
  { id: 154, question: "Navlun piyasası çok yüksekken hız artırmak neden ekonomik olabilir?", options: ["Sigorta primi düştüğü için ekonomiktir", "Yakıt fiyatı düştüğü için ekonomiktir", "Ek sefer getirisi yakıt maliyetini aştığı için", "Bakım gereksinimi azaldığı için ekonomiktir"], correctAnswer: 2, explanation: "Yüksek navlun ortamında zaman değerlidir; ek yakıt maliyeti ilave sefer gelirinin altında kalabilir.", category: "Yakıt/Bunker" },
  { id: 155, question: "Denizcilikte ETS/karbon fiyatlamasının işletmeye etkisi nedir?", options: ["Emisyon başına maliyet doğurup verimliyi öne çıkarır", "Yalnızca yeni inşa edilen gemileri etkilemektedir", "Yalnızca yolcu ve ro-ro gemilerini etkilemektedir", "İşletme maliyeti üzerinde hiçbir etkisi olmaz"], correctAnswer: 0, explanation: "Karbon maliyeti sefer bütçesine girer; bu maliyetin çarter tarafları arasında nasıl paylaşılacağı sözleşmelerde düzenlenir.", category: "Gemi Maliyetleri" },
  { id: 156, question: "Zaman çarterinde karbon maliyetinin kime ait olacağı neden sözleşmede düzenlenmelidir?", options: ["Sigorta priminin bundan etkilenmesi nedeniyle", "Bayrak devleti vergisi doğurması nedeniyle", "Liman ücretlerini artırması nedeniyle", "Yakıtı kiracı alır, verimliliği donatan belirler"], correctAnswer: 3, explanation: "Emisyon hem geminin teknik verimliliğine hem de kiracının hız/rota kararlarına bağlıdır; BIMCO bu paylaşım için standart maddeler yayımlamıştır.", category: "Çarter Parti Maddeleri" },
  { id: 157, question: "Sefer çarteri altında boşaltma limanına vardınız; serbest rıhtım yok, demirde bekliyorsunuz ve charter party WIBON şartı içeriyor. Kiracı 'rıhtıma yanaşmadan NOR verilemez' diyor. Ne yaparsınız?", options: ["Gemi hazırsa WIBON gereği demirde yazılı NOR veririm", "Kiracı haklıdır; rıhtıma yanaşana kadar NOR vermem", "NOR'u sözlü veririm, ayrıca kayıt tutmam", "NOR yerine acenteye bilgi notu gönderip beklerim"], correctAnswer: 0, explanation: "'Whether in berth or not' şartı, rıhtım müsait olmasa da gemi hazırsa geçerli NOR verilmesini sağlar; laytime sözleşmedeki bekleme (turn time) sonrası işlemeye başlar. NOR yazılı verilmeli ve Statement of Facts'e işlenmelidir.", category: "Laytime/NOR" },
  { id: 158, question: "Boşaltma başladı ancak liman tatili ve kötü hava nedeniyle aralar oldu; charter party 'weather working days, SHEX' diyor. Laytime sayımını nasıl yaparsınız?", options: ["Geçen sürenin tamamını laytime olarak sayarım", "Kötü hava ile tatilleri düşer, SOF ile belgelerim", "Yalnızca tatilleri düşer, kötü havayı sayarım", "Sayımı bitişte toplam süreden tahminle yaparım"], correctAnswer: 1, explanation: "'Weather working days' kötü hava nedeniyle çalışılamayan süreyi, 'SHEX' (Sundays and Holidays Excepted) tatil ve pazar günlerini laytime dışında bırakır; gerçek olaylar time sheet ve Statement of Facts ile belgelenir.", category: "Laytime/NOR" },
  { id: 159, question: "Bir voyage teklifinde navlun 1.2 milyon USD, tahmini sefer maliyeti (bunker + liman + kanal) 500 bin USD ve sefer süresi 25 gündür. TCE kaç USD/gün'dür?", options: ["48.000 USD/gün", "28.000 USD/gün", "20.000 USD/gün", "68.000 USD/gün"], correctAnswer: 1, explanation: "TCE = (navlun − sefer maliyetleri) / sefer günü = (1.200.000 − 500.000) / 25 = 28.000 USD/gün. Sefer maliyetleri düşülmeden bulunan 48.000 USD/gün yanıltıcıdır.", category: "Navlun/TCE" },
  { id: 160, question: "Voyage seferinin TCE'si 28.000 USD/gün, alternatif time charter hire'ı 20.000 USD/gün ve geminin günlük OPEX'i 8.000 USD. Hangi teklif ticari olarak daha cazip?", options: ["Time charter; sabit gelir her zaman daha iyidir", "İkisi karşılaştırılamaz; TCE ile hire farklı ölçülerdir", "Voyage charter; TCE hire'ın üzerinde olduğundan net getirisi yüksektir", "İki teklif de OPEX'i karşılamadığından ikisi de reddedilir"], correctAnswer: 2, explanation: "TCE, sefer gelirini günlük hire ile doğrudan karşılaştırılabilir hâle getirir; 28.000 > 20.000 olduğundan voyage daha kârlıdır. Kararda ayrıca sonraki ballast leg (konumlanma) ve risk iştahı gözetilir.", category: "Navlun/TCE" },
  { id: 161, question: "Kuru dökme yük piyasasında Capesize alt endeksi hangi segmenti temsil eder?", options: ["Yaklaşık 180.000 DWT sınıfı büyük dökme yük gemilerini", "Yaklaşık 35.000 DWT sınıfı küçük dökme yük gemilerini", "Yaklaşık 75.000 DWT sınıfı orta dökme yük gemilerini", "Yaklaşık 300.000 DWT sınıfı ham petrol tankerlerini"], correctAnswer: 0, explanation: "Baltic Dry Index alt endeksleri gemi sınıfına göre ayrılır: Capesize (~180.000 DWT), Panamax (~75.000 DWT), Supramax (~58.000 DWT) ve Handysize (~35.000 DWT).", category: "Navlun/TCE" },
  { id: 162, question: "Navlun piyasasında arzın kısa vadede esnek olmaması ne sonuç doğurur?", options: ["Oranlar talep değişimine karşı durağan kalır", "Oranlar talep değişiminde keskin biçimde oynar", "Oranlar yalnızca yakıt fiyatıyla belirlenir", "Oranlar liman ücretlerine bağlı olarak sabitlenir"], correctAnswer: 1, explanation: "Yeni gemi teslimi 2-3 yıl aldığından kısa vadede filo büyüklüğü sabittir; talep arttığında oranlar hızla yükselir, talep düştüğünde çöker.", category: "Navlun/TCE" },
  { id: 163, question: "Denizcilikte 'karşı taraf riski' (counterparty risk) neyi ifade eder?", options: ["Geminin klas sörveyini geçememe olasılığını", "Yakıt fiyatının sefer sırasında yükselmesini", "Kiracının hire veya navlunu ödememe olasılığını", "Liman ücretlerinin yıl içinde artırılmasını"], correctAnswer: 2, explanation: "Piyasa düşüşlerinde kiracılar sözleşmeden kaçabilir veya ödeme yapamaz; bu yüzden fikstür öncesi kiracının mali durumu araştırılır.", category: "Gemi Finansmanı" },
  { id: 164, question: "FFA (Forward Freight Agreement) hangi riski yönetmek için kullanılır?", options: ["Yük hasarından doğan sorumluluk riskini", "Gelecekteki navlun oranı dalgalanma riskini", "Mürettebat kaynaklı operasyonel riski", "Bayrak devleti mevzuat değişikliği riskini"], correctAnswer: 1, explanation: "FFA, belirli bir rota ve dönem için navlun oranını finansal olarak sabitleyen nakdi uzlaşmalı türev sözleşmedir; fiziki taşıma içermez.", category: "Navlun/TCE" },
  { id: 165, question: "İkinci el gemi değerini belirleyen en güçlü etken hangisidir?", options: ["Geminin bayrağı ve sicil ülkesi", "Geminin boya ve iç donanım durumu", "Mürettebat sözleşmelerinin süresi", "Piyasanın o anki navlun seviyesi"], correctAnswer: 3, explanation: "Yaş, tip ve sörvey statüsü etkili olsa da gemi değeri esas olarak beklenen kazançla, yani cari ve beklenen navlun seviyesiyle belirlenir.", category: "Gemi Finansmanı" },
  { id: 166, question: "Piyasa zirvesinde yeni inşa siparişi vermenin tipik riski nedir?", options: ["Geminin teslim alınamaması riski", "Teslimin talep düşüşüne denk gelmesi", "İnşa maliyetinin sabit kalması riski", "Klas kuruluşunun onay vermemesi"], correctAnswer: 1, explanation: "Zirvede verilen siparişler 2-3 yıl sonra, çoğu kez piyasa gerilerken teslim edilir; arz artışı düşüşü derinleştirir. Bu, shipping cycle'ın klasik döngüsüdür.", category: "Gemi Finansmanı" },
  { id: 167, question: "Ham petrol tankeri piyasasında navlun oranı hangi ölçekle kote edilir?", options: ["Worldscale (WS) yüzde ölçeğiyle", "Baltic Dry Index puanıyla", "USD/LDT birimiyle", "TEU başına dolar tutarıyla"], correctAnswer: 0, explanation: "Worldscale'de WS100 referans (flat) haddi gösterir; kote edilen WS değeri bu referansın yüzdesidir. USD/LDT hurda, TEU ise konteyner birimidir.", category: "Navlun/TCE" },
  { id: 168, question: "Donatanın navlun riskini azaltmak için portföyünü nasıl kurması beklenir?", options: ["Tüm filoyu tek bir spot rotaya bağlaması", "Tüm filoyu tek kiracıya uzun süre vermesi", "Spot ve dönem işlerini dengeli biçimde karması", "Tüm gemileri lay-up konumunda tutması"], correctAnswer: 2, explanation: "Spot işler yükselen piyasada getiriyi artırır, dönem çarterleri düşüşte nakit akışını korur; karma portföy oynaklığı azaltır.", category: "Gemi Finansmanı" },
  { id: 169, question: "Navlun geliri hesaplanırken brüt navlundan hangi kalem düşülür?", options: ["Geminin günlük işletme gideri (OPEX)", "Kredi anapara ve faiz ödemeleri", "Broker ve adres komisyonları", "Geminin yıllık amortisman payı"], correctAnswer: 2, explanation: "Net navlun = brüt navlun − broker komisyonu − adres komisyonu. OPEX ve finansman giderleri navlun gelirinden değil, kârlılık hesabından düşülür.", category: "Navlun/TCE" },
  { id: 170, question: "Sefer geliri değerlendirilirken 'ballast leg' neden hesaba katılır?", options: ["Yüksüz seyir süresi ve yakıtı da sefere ait olduğu için", "Yüksüz seyirde sigorta primi arttığı için", "Yüksüz seyirde liman ücreti ödendiği için", "Yüksüz seyirde mürettebat ücreti arttığı için"], correctAnswer: 0, explanation: "TCE, yükleme limanına gidiş (ballast) süresini ve yakıtını da içeren tam sefer üzerinden hesaplanır; yalnızca yüklü ayak dikkate alınırsa kazanç olduğundan yüksek görünür.", category: "Navlun/TCE" },
];
